<?php
require __DIR__ . '/../../app/bootstrap.php'; require_admin_api(); $in=json_input();
$name=trim((string)($in['name']??''));$scenario=trim((string)($in['scenario']??''));$agent=trim((string)($in['agent_name']??'Voice Agent'));$deviceId=(int)($in['device_id']??0);$numbers=$in['numbers']??[];
if(!$name||!$scenario||!$deviceId||!is_array($numbers)||!$numbers) json_response(['ok'=>false,'error'=>'Missing campaign fields'],422);
$pdo=db();$chk=$pdo->prepare('SELECT id FROM devices WHERE id=? AND revoked_at IS NULL');$chk->execute([$deviceId]);if(!$chk->fetch())json_response(['ok'=>false,'error'=>'Device not found'],404);
$pdo->beginTransaction();try{$s=$pdo->prepare("INSERT INTO campaigns(name,scenario,agent_name,device_id,status,created_at,started_at) VALUES(?,?,?,?, 'running',?,?)");$s->execute([$name,$scenario,$agent,$deviceId,now_utc(),now_utc()]);$cid=(int)$pdo->lastInsertId();$c=$pdo->prepare("INSERT INTO campaign_contacts(campaign_id,phone_number,status,created_at) VALUES(?,?, 'pending',?)");$count=0;foreach($numbers as $n){$p=normalize_phone((string)$n);if(strlen($p)<8)continue;$c->execute([$cid,$p,now_utc()]);$count++;}if(!$count)throw new RuntimeException('No valid phone numbers');$pdo->commit();json_response(['ok'=>true,'campaign_id'=>$cid,'contacts'=>$count],201);}catch(Throwable $e){$pdo->rollBack();json_response(['ok'=>false,'error'=>$e->getMessage()],422);}
